        algorithms = params.get("algorithms", ["sha256"])
        chunk_size = self.config.get("chunk_size", 8192)
        results = {}

        hashers = {alg: hashlib.new(alg) for alg in algorithms if alg in hashlib.algorithms_available}

        try:
            with open(path, "rb") as f:
